public sealed class LibraryFolder {public required string Path{get;init;}public string Name=>System.IO.Path.GetFileName(System.IO.Path.TrimEndingDirectorySeparator(Path)) is string n&&n.Length>0?n:Path;public List<LibraryFolder> Children{get;}=new();public List<string> DirectFiles{get;}=new();public string[] Members{get;set;}=Array.Empty<string>();}
public static class LibraryTreeLogic {
 public static bool Matches(string name,string[] words,bool any)=>words.Length==0||(any?words.Any(w=>name.Contains(w,StringComparison.OrdinalIgnoreCase)):words.All(w=>name.Contains(w,StringComparison.OrdinalIgnoreCase)));
 public static List<LibraryFolder> Build(IEnumerable<string> paths){var byPath=new Dictionary<string,LibraryFolder>(StringComparer.OrdinalIgnoreCase);var roots=new List<LibraryFolder>();LibraryFolder Ensure(string path){path=System.IO.Path.GetFullPath(path);if(byPath.TryGetValue(path,out var found))return found;var node=new LibraryFolder{Path=path};byPath.Add(path,node);string? parent=System.IO.Path.GetDirectoryName(System.IO.Path.TrimEndingDirectorySeparator(path));if(parent==null||parent.Equals(path,StringComparison.OrdinalIgnoreCase))roots.Add(node);else Ensure(parent).Children.Add(node);return node;}foreach(string path in paths.Distinct(StringComparer.OrdinalIgnoreCase)){string full=System.IO.Path.GetFullPath(path);Ensure(System.IO.Path.GetDirectoryName(full)!).DirectFiles.Add(full);}string[] Members(LibraryFolder n){n.Members=n.DirectFiles.Concat(n.Children.SelectMany(Members)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();return n.Members;}foreach(var root in roots)Members(root);return roots;}
 public static void Verify(){if(!Matches("القانون المدني المصري",new[]{"المصري","القانون"},false)||Matches("القانون المدني",new[]{"القانون","جنائي"},false)||!Matches("القانون المدني",new[]{"القانون","جنائي"},true)||Matches("المدني",new[]{"جنائي","تجاري"},true))throw new InvalidOperationException("Name filter regression");string root=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"AnsaryScopeTest"),a=System.IO.Path.Combine(root,"alpha","a.docx"),b=System.IO.Path.Combine(root,"alpha","sub","b.docx"),c=System.IO.Path.Combine(root,"alphabet","c.docx");var tree=Build(new[]{a,b,c});IEnumerable<LibraryFolder> Walk(LibraryFolder n){yield return n;foreach(var child in n.Children)foreach(var x in Walk(child))yield return x;}var folder=tree.SelectMany(Walk).Single(n=>n.Path.Equals(System.IO.Path.GetDirectoryName(a),StringComparison.OrdinalIgnoreCase));if(!new HashSet<string>(folder.Members,StringComparer.OrdinalIgnoreCase).SetEquals(new[]{a,b})||Build(Array.Empty<string>()).Count!=0)throw new InvalidOperationException("Recursive library scope regression");}
}
